mod scoreboard {
    const MAX_POINTS: u32 = 100;

    pub struct Player {
        pub name: String,
        points: u32,
    }

    impl Player {
        pub fn new(name: &str) -> Player {
            Player { name: String::from(name), points: 0 }
        }

        pub fn points(&self) -> u32 {
            self.points
        }

        // Adds points, but the total never goes above MAX_POINTS.
        pub fn add_points(&mut self, amount: u32) {
            self.points += amount;
            if self.points > MAX_POINTS {
                self.points = MAX_POINTS;
            }
        }

        // Takes points away. Fails, and changes nothing, if there are too few.
        pub fn spend(&mut self, cost: u32) -> Result<(), String> {
            if cost > self.points {
                return Err(format!("{} needs {} more points", self.name, cost - self.points));
            }
            self.points -= cost;
            Ok(())
        }
    }

    pub mod rank {
        use super::Player;

        // A child module may read the private field of its parent's struct.
        pub fn title(player: &Player) -> &'static str {
            match player.points {
                0..=9 => "rookie",
                10..=49 => "regular",
                50..=99 => "expert",
                _ => "legend",
            }
        }
    }
}

use scoreboard::{Player, rank};

fn main() {
    let mut ada = Player::new("Ada");
    println!("{}: {} points, {}", ada.name, ada.points(), rank::title(&ada));

    ada.add_points(40);
    assert_eq!(ada.points(), 40);
    println!("{}: {} points, {}", ada.name, ada.points(), rank::title(&ada));

    for cost in [60, 15] {
        match ada.spend(cost) {
            Ok(()) => println!("spent {cost}"),
            Err(e) => println!("error: {e}"),
        }
    }
    assert_eq!(ada.points(), 25);

    ada.add_points(500);
    assert_eq!(ada.points(), 100);
    println!("{}: {} points, {}", ada.name, ada.points(), rank::title(&ada));

    ada.spend(51).unwrap();
    println!("{}: {} points, {}", ada.name, ada.points(), rank::title(&ada));
    println!("all checks passed");
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn points_are_capped() {
        let mut p = Player::new("Bo");
        p.add_points(90);
        p.add_points(90);
        assert_eq!(p.points(), 100);
    }

    #[test]
    fn spend_fails_when_too_poor() {
        let mut p = Player::new("Bo");
        p.add_points(5);
        assert!(p.spend(6).is_err());
        assert_eq!(p.points(), 5);
    }
